class Solution {
    public int kthSmallest(int[][] mat,int k){
        List<Integer> sums=new ArrayList<>();
        sums.add(0);
        for(int[] row:mat){
            List<Integer> merged=new ArrayList<>();
            for(int sum:sums)for(int value:row)merged.add(sum+value);
            Collections.sort(merged);
            sums=new ArrayList<>(merged.subList(0,Math.min(k,merged.size())));
        }
        return sums.get(k-1);
    }
}

code.kotlin:
class Solution {
    fun kthSmallest(mat:Array<IntArray>,k:Int):Int{
        var sums=listOf(0);
        for(row in mat)sums=sums.flatMap{
            sum->row.map{
                sum+it
            }
        }.sorted().take(k);
        return sums[k-1]
    }
}

code.cpp:
class Solution {
    public: int kthSmallest(vector<vector<int>>& mat,int k){
        vector<int> sums{
            0
        };
        for(auto& row:mat){
            vector<int> merged;
            for(int sum:sums)for(int value:row)merged.push_back(sum+value);
            sort(merged.begin(),merged.end());
            if((int)merged.size()>k)merged.resize(k);
            sums=move(merged);
        }
        return sums[k-1];
    }
};
